pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 toSeed) public {
        // admissible domain: positive deposit, recipient a normal (non-precompile) codeless address
        amount = bound(amount, 1, address(this).balance > 0 ? address(this).balance : 1);
        vm.deal(address(this), amount);
        uint160 toRaw = uint160(bound(toSeed, 10, type(uint160).max));
        address to = address(toRaw);
        vm.assume(to.code.length == 0);
        vm.assume(to != address(c) && to != address(this));

        // fund the contract via a deposit by the creator (deployer == address(this))
        c.deposit{value: amount}();
        uint256 cBal = address(c).balance;
        uint256 toBefore = to.balance;

        vm.prank(address(this));
        c.migrateTo(to);

        uint256 toAfter = to.balance;
        assertTrue(toAfter == toBefore + cBal && address(c).balance == 0);
    }
}

