        c.migrateTo(recipient);

        // Reference: recipient's balance grew by exactly the contract's balance.
        // Mutant: transfers 0, so the recipient's balance is unchanged.
        assertTrue(recipient.balance == amount, "migration must move full balance to recipient");
    }
}

