pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address recipient) public {
        vm.assume(amount > 0 && amount <= 1e18);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(recipient != address(c) && recipient != address(this));

        // depositor funds the contract
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // creator (the deployer of c) migrates all funds out
        vm.prank(address(this));
        c.migrateTo(recipient);

        // General rule: migration empties the contract, so any depositor's
        // refund can no longer pay out and must revert.
        bool ok;
        vm.prank(actor);
        try c.refund() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

